code_string = """
from qiskit import transpile
from scipy.optimize import minimize

def run_and_analyze(circuit, aer_sim, graph):
    def to_bitstring(counts):
        result = {}
        for hex_key, count in counts.items():
            bitstring = format(int(hex_key, 16), f'0{8}b')
            result[bitstring] = count
        return result

    def objective(params):
        parameter_binds = [{circuit.parameters[i]: [params[i]] for i in range(len(params))}]
        result = aer_sim.run(circuit, parameter_binds=parameter_binds).result()
        counts = result.get_counts(0)
        counts_bitstring = to_bitstring(counts)
        return -compute_expectation(counts_bitstring, graph)

    best_result = None
    best_energy = float('inf')

    for seed in range(5):
        x0 = [float('0.01') + 0.1 * (i % 3) + seed * 0.5 for i in range(circuit.num_parameters)]
        result = minimize(objective, x0, method='L-BFGS-B', bounds=[(0, 6.28)] * circuit.num_parameters)
        if result.fun < best_energy:
            best_energy = result.fun
            best_result = result.x

    parameter_binds = [{circuit.parameters[i]: [best_result[i]] for i in range(len(best_result))}]
    result = aer_sim.run(circuit, parameter_binds=parameter_binds).result()
    counts = result.get_counts(0)
    counts_bitstring = to_bitstring(counts)

    sorted_counts = sorted(counts_bitstring.items(), key=lambda x: x[1], reverse=True)
    top_two = [item[0] for item in sorted_counts[:2]]

    return top_two
"""

